using UnityEngine;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        var doc = hud.GetComponent<UIDocument>();
        var root = doc.rootVisualElement;
        var bindings = hud.GetComponent<Homesteader.UI.HudBindings>();
        if (bindings != null)
        {
            bindings.SendMessage("Update", SendMessageOptions.DontRequireReceiver);
        }
        var fillWellness = root.Q<VisualElement>("VitalWellnessFill");
        var fillStamina  = root.Q<VisualElement>("VitalStaminaFill");
        var fillThirst   = root.Q<VisualElement>("VitalThirstFill");
        var fillHunger   = root.Q<VisualElement>("VitalHungerFill");
        result.Log("VitalWellnessFill width=" + (fillWellness != null ? fillWellness.style.width.value : -1f) + " %; rawValue=" + Homesteader.UI.HudState.Active.Vitals[Homesteader.UI.VitalId.Wellness].Value);
        result.Log("VitalStaminaFill  width=" + (fillStamina != null ? fillStamina.style.width.value : -1f) + " %");
        result.Log("VitalThirstFill   width=" + (fillThirst != null ? fillThirst.style.width.value : -1f) + " %");
        result.Log("VitalHungerFill   width=" + (fillHunger != null ? fillHunger.style.width.value : -1f) + " %");
        var pcts = new string[] { "VitalWellnessPct", "VitalStaminaPct", "VitalThirstPct", "VitalHungerPct" };
        foreach (var n in pcts)
        {
            var l = root.Q<Label>(n);
            result.Log(n + " text=" + (l != null ? l.text : "?"));
        }
    }
}
